:"Service","name":"Farm, Barn & Equine Property Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/farm-equine-property-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/second-look-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/neutral-umpire-services/"}}]},"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://kentuckyinsuranceappraiser.com/#website","url":"https://kentuckyinsuranceappraiser.com/","name":"Kentucky Insurance Appraiser","publisher":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/#webpage","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/","name":"Kentucky Insurance Appraisal Process | 7 Steps","description":"Step-by-step guide to the Kentucky insurance appraisal process: written demand, party appraisers, umpire selection, negotiation and the binding award.","inLanguage":"en-US","isPartOf":{"@id":"https://kentuckyinsuranceappraiser.com/#website"},"about":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"publisher":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","breadcrumb":{"@id":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/#breadcrumb"},"primaryImageOfPage":{"@type":"ImageObject","@id":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/#primaryimage","url":"https://kentuckyinsuranceappraiser.com/assets/img/photos/paperwork.webp","width":960,"height":641,"caption":"Hands taking notes on paper between two laptops"},"mainEntity":{"@id":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/#howto"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://kentuckyinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal process","item":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"}],"@id":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/#breadcrumb"},{"@type":"HowTo","name":"How the insurance appraisal process works in Kentucky","description":"The seven stages of a property insurance appraisal under a typical policy appraisal clause.","step":[{"@type":"HowToStep","position":1,"name":"Confirm it is a pricing dispute","text":"Check that you and the insurer agree a covered loss happened and disagree mainly about how much it costs to repair or replace.","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"},{"@type":"HowToStep","position":2,"name":"Send a written appraisal demand","text":"Invoke the appraisal clause in writing, following the notice requirements in your policy.","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"},{"@type":"HowToStep","position":3,"name":"Name your party appraiser","text":"Each side selects a competent, impartial appraiser within the window most policies set after the demand.","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"},{"@type":"HowToStep","position":4,"name":"Select the umpire","text":"The two appraisers agree on a neutral umpire, or a court of record where the property sits can appoint one.","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"},{"@type":"HowToStep","position":5,"name":"Inspect and build estimates","text":"The appraisers inspect the property, review the documents and each prepare a line-item estimate of the loss.","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"},{"@type":"HowToStep","position":6,"name":"Negotiate and narrow the differences","text":"The appraisers work through the line items together and send only the items they cannot resolve to the umpire.","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"},{"@type":"HowToStep","position":7,"name":"Sign the award and collect payment","text":"A written award signed by any two of the three sets the amount of loss, and the insurer pays under the policy terms.","url":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/"}],"@id":"https://kentuckyinsuranceappraiser.com/kentucky-appraisal-process/#howto"}]}</script>
